/*
 * WAV parsing for the embedded clip.
 *
 * The file is linked as a binary blob (see CMakeLists: EMBED_FILES). Only the
 * canonical PCM16 mono layout is accepted, which is what the bundled
 * notify.wav uses; the parser validates every chunk length, so a corrupt file
 * fails cleanly instead of reading out of bounds.
 */
#include "audio_clip.h"

#include <stdbool.h>
#include <stdlib.h>
#include <string.h>

#include "esp_log.h"

/* Generated by the linker for main/notify.wav. */
extern const uint8_t notify_wav_start[] asm("_binary_notify_wav_start");
extern const uint8_t notify_wav_end[] asm("_binary_notify_wav_end");

static const char *TAG = "audio_clip";

static audio_clip_t s_clip;
static bool s_parsed;
static bool s_valid;

static uint16_t rd16(const uint8_t *p)
{
    return (uint16_t)(p[0] | (p[1] << 8));
}

static uint32_t rd32(const uint8_t *p)
{
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) |
           ((uint32_t)p[3] << 24);
}

static bool chunk_is(const uint8_t *p, const char *tag)
{
    return memcmp(p, tag, 4) == 0;
}

static bool parse_wav(const uint8_t *data, size_t len)
{
    if (len < 12 || !chunk_is(data, "RIFF") || !chunk_is(data + 8, "WAVE")) {
        ESP_LOGE(TAG, "not a RIFF/WAVE file");
        return false;
    }

    bool fmt_ok = false;
    uint32_t sample_rate = 0;
    const uint8_t *pcm = NULL;
    size_t pcm_len = 0;

    size_t pos = 12;
    while (pos + 8 <= len) {
        const uint32_t size = rd32(data + pos + 4);
        const uint8_t *body = data + pos + 8;
        if (pos + 8 + size > len) {
            ESP_LOGW(TAG, "truncated chunk at %u", (unsigned)pos);
            break;
        }
        if (chunk_is(data + pos, "fmt ") && size >= 16) {
            const uint16_t format = rd16(body);
            const uint16_t channels = rd16(body + 2);
            sample_rate = rd32(body + 4);
            const uint16_t bits = rd16(body + 14);
            fmt_ok = (format == 1 && channels == 1 && bits == 16 && sample_rate > 0);
            if (!fmt_ok) {
                ESP_LOGE(TAG, "unsupported WAV: format=%u ch=%u bits=%u",
                         format, channels, bits);
            }
        } else if (chunk_is(data + pos, "data")) {
            pcm = body;
            pcm_len = size;
        }
        pos += 8 + size + (size & 1); /* chunks are word aligned */
    }

    if (!fmt_ok || pcm == NULL || pcm_len < 2) {
        return false;
    }

    /* Copy into a properly aligned buffer; the blob itself has no guarantee. */
    int16_t *samples = malloc(pcm_len);
    if (samples == NULL) {
        ESP_LOGE(TAG, "no memory for the clip");
        return false;
    }
    memcpy(samples, pcm, pcm_len);

    s_clip.pcm = samples;
    s_clip.frames = pcm_len / sizeof(int16_t);
    s_clip.sample_rate = sample_rate;
    return true;
}

const audio_clip_t *audio_clip_default(void)
{
    if (!s_parsed) {
        const size_t len = (size_t)(notify_wav_end - notify_wav_start);
        s_valid = parse_wav(notify_wav_start, len);
        s_parsed = true;
        if (s_valid) {
            ESP_LOGI(TAG, "clip ready: %u samples @ %lu Hz (%.2f s)",
                     (unsigned)s_clip.frames, (unsigned long)s_clip.sample_rate,
                     (double)s_clip.frames / (double)s_clip.sample_rate);
        }
    }
    return s_valid ? &s_clip : NULL;
}
